SourceCode.Declaration:
/// <summary>
/// getBarcode response: the item (and variant) a barcode identifies, and how many of UnitId one scan is. ItemId blank = not a barcode.
/// </summary>
[DataContractAttribute]
class HSMobileOpsBarcodeResponse
{
    boolean success;
    str errorCode;
    str itemId;
    real quantity;
    str unitId;
    str configId;
    str sizeId;
    str colorId;
    str styleId;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('ItemId')]
public str parmItemId(str _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('Quantity')]
public real parmQuantity(real _value = quantity)
{
    quantity = _value;
    return quantity;
}

[DataMemberAttribute('UnitId')]
public str parmUnitId(str _value = unitId)
{
    unitId = _value;
    return unitId;
}

[DataMemberAttribute('ConfigId')]
public str parmConfigId(str _value = configId)
{
    configId = _value;
    return configId;
}

[DataMemberAttribute('SizeId')]
public str parmSizeId(str _value = sizeId)
{
    sizeId = _value;
    return sizeId;
}

[DataMemberAttribute('ColorId')]
public str parmColorId(str _value = colorId)
{
    colorId = _value;
    return colorId;
}

[DataMemberAttribute('StyleId')]
public str parmStyleId(str _value = styleId)
{
    styleId = _value;
    return styleId;
}
